SELECT
  CASE WHEN (CAST(ROUND(SUBSTR("2024-01-01", 6, 2)) AS BIGINT) = 2) THEN CASE WHEN ((((MOD(CAST(ROUND(SUBSTR("2024-01-01", 1, 4)) AS BIGINT), NULLIF(4, 0))) = 0) AND ((MOD(CAST(ROUND(SUBSTR("2024-01-01", 1, 4)) AS BIGINT), NULLIF(100, 0))) != 0)) OR ((MOD(CAST(ROUND(SUBSTR("2024-01-01", 1, 4)) AS BIGINT), NULLIF(400, 0))) = 0)) THEN 29 ELSE 28 END ELSE (CASE WHEN ((CAST(ROUND(SUBSTR("2024-01-01", 6, 2)) AS BIGINT)) - (1)) < 0 THEN NULL ELSE ELEMENT_AT(ARRAY(31, 0, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31), CAST(((CAST(ROUND(SUBSTR("2024-01-01", 6, 2)) AS BIGINT)) - (1)) AS INT) + 1) END) END AS n;